#!/usr/bin/env node
'use strict';
/**
 * bk-precommit-install.cjs — Pre-commit hook installer.
 *
 * Usage:
 *   node bk-precommit-install.cjs [--framework=husky|pre-commit|native] [--force]
 *
 * Auto-detects which pre-commit framework is in use:
 *   - "husky"      → checks package.json for husky
 *   - "pre-commit" → checks for .pre-commit-config.yaml
 *   - "native"     → default, writes .git/hooks/pre-commit
 *
 * Refuses to overwrite existing hooks without --force.
 */

const fs = require('fs');
const path = require('path');
const os = require('os');

// ─── Arg parsing ──────────────────────────────────────────────────────────────

function parseArgs(argv) {
  const args = argv.slice(2);
  const opts = {
    framework: null,   // auto-detect if null
    force: false,
    projectRoot: null,
    dryRun: false
  };

  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a.startsWith('--framework=')) opts.framework = a.slice('--framework='.length);
    else if (a === '--framework' && args[i + 1]) opts.framework = args[++i];
    else if (a === '--force') opts.force = true;
    else if (a === '--dry-run') opts.dryRun = true;
    else if (a.startsWith('--project-root=')) opts.projectRoot = a.slice('--project-root='.length);
    else if (a === '--project-root' && args[i + 1]) opts.projectRoot = args[++i];
  }

  return opts;
}

// ─── Framework detection ─────────────────────────────────────────────────────

/**
 * Detect which pre-commit framework is configured in the project.
 * @param {string} projectRoot
 * @returns {'husky' | 'pre-commit' | 'native'}
 */
function detectFramework(projectRoot) {
  // Check for husky in package.json
  const pkgPath = path.join(projectRoot, 'package.json');
  if (fs.existsSync(pkgPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
      if (pkg.devDependencies?.husky || pkg.dependencies?.husky || pkg.husky) {
        return 'husky';
      }
    } catch { /* fall through */ }
  }

  // Check for pre-commit framework config
  const preCommitConfig = path.join(projectRoot, '.pre-commit-config.yaml');
  if (fs.existsSync(preCommitConfig)) {
    return 'pre-commit';
  }

  return 'native';
}

// ─── Hook content generators ──────────────────────────────────────────────────

/**
 * Generate the native .git/hooks/pre-commit shell script.
 * @param {string} projectRoot
 * @returns {string}
 */
function generateNativeHook(projectRoot) {
  return `#!/bin/sh
# bk-harness pre-commit hook — auto-generated by bk-precommit-install.cjs
# Do not edit directly; re-run bk-precommit-install.cjs to regenerate.
set -e

BUDGET="\${BK_PR_BUDGET:-5}"
BK_PROJECT_ROOT="${projectRoot}"

# Locate the bk-harness-ci CLI
BK_CI_CLI=""
if [ -f "\${BK_PROJECT_ROOT}/.claude/cli/bk-harness-ci/index.cjs" ]; then
  BK_CI_CLI="\${BK_PROJECT_ROOT}/.claude/cli/bk-harness-ci/index.cjs"
elif [ -f "\${BK_PROJECT_ROOT}/src/cli/bk-harness-ci/index.cjs" ]; then
  BK_CI_CLI="\${BK_PROJECT_ROOT}/src/cli/bk-harness-ci/index.cjs"
fi

if [ -z "\$BK_CI_CLI" ]; then
  echo "[bk-harness] WARNING: bk-harness-ci not found, skipping validation" >&2
  exit 0
fi

echo "[bk-harness] Running pre-commit harness validation..."
BK_PROJECT_ROOT="\${BK_PROJECT_ROOT}" node "\${BK_CI_CLI}" \\
  --fail-on=error \\
  --budget-usd="\${BUDGET}" \\
  --format=console
`;
}

/**
 * Generate the husky hook content.
 * @param {string} projectRoot
 * @returns {string}
 */
function generateHuskyHook(projectRoot) {
  return `#!/bin/sh
. "\$(dirname "\$0")/_/husky.sh"

# bk-harness pre-commit validation
BUDGET="\${BK_PR_BUDGET:-5}"
BK_PROJECT_ROOT="${projectRoot}" node .claude/cli/bk-harness-ci/index.cjs \\
  --fail-on=error \\
  --budget-usd="\${BUDGET}" \\
  --format=console
`;
}

/**
 * Generate the pre-commit framework YAML block to append.
 * @returns {string}
 */
function generatePreCommitBlock() {
  return `
# bk-harness validation — added by bk-precommit-install.cjs
- repo: local
  hooks:
    - id: bk-harness-ci
      name: Beer Kit Harness CI Validation
      language: node
      entry: node .claude/cli/bk-harness-ci/index.cjs --fail-on=error --format=console
      pass_filenames: false
      always_run: true
`;
}

// ─── Installers ───────────────────────────────────────────────────────────────

function installNative(projectRoot, opts) {
  const gitDir = path.join(projectRoot, '.git');
  if (!fs.existsSync(gitDir)) {
    throw new Error(`No .git directory found at ${projectRoot}. Is this a git repository?`);
  }

  const hooksDir = path.join(gitDir, 'hooks');
  if (!fs.existsSync(hooksDir)) {
    fs.mkdirSync(hooksDir, { recursive: true });
  }

  const hookPath = path.join(hooksDir, 'pre-commit');

  if (fs.existsSync(hookPath) && !opts.force) {
    throw new Error(
      `Pre-commit hook already exists at ${hookPath}. Use --force to overwrite.`
    );
  }

  const content = generateNativeHook(projectRoot);

  if (opts.dryRun) {
    process.stdout.write(`[dry-run] Would write to ${hookPath}:\n${content}\n`);
    return { installed: true, path: hookPath, framework: 'native', dryRun: true };
  }

  fs.writeFileSync(hookPath, content, { mode: 0o755, encoding: 'utf8' });
  return { installed: true, path: hookPath, framework: 'native' };
}

function installHusky(projectRoot, opts) {
  const huskyDir = path.join(projectRoot, '.husky');
  if (!fs.existsSync(huskyDir)) {
    if (opts.dryRun) {
      process.stdout.write(`[dry-run] Would create directory ${huskyDir}\n`);
    } else {
      fs.mkdirSync(huskyDir, { recursive: true });
    }
  }

  const hookPath = path.join(huskyDir, 'pre-commit');

  if (fs.existsSync(hookPath) && !opts.force) {
    throw new Error(
      `Husky pre-commit hook already exists at ${hookPath}. Use --force to overwrite.`
    );
  }

  const content = generateHuskyHook(projectRoot);

  if (opts.dryRun) {
    process.stdout.write(`[dry-run] Would write to ${hookPath}:\n${content}\n`);
    return { installed: true, path: hookPath, framework: 'husky', dryRun: true };
  }

  fs.writeFileSync(hookPath, content, { mode: 0o755, encoding: 'utf8' });
  return { installed: true, path: hookPath, framework: 'husky' };
}

function installPreCommit(projectRoot, opts) {
  const configPath = path.join(projectRoot, '.pre-commit-config.yaml');

  if (!fs.existsSync(configPath)) {
    // Create minimal config
    const minimal = `repos: []\n`;
    if (!opts.dryRun) {
      fs.writeFileSync(configPath, minimal, 'utf8');
    }
  }

  // Check if bk-harness hook already present
  const existing = fs.existsSync(configPath) ? fs.readFileSync(configPath, 'utf8') : '';
  if (existing.includes('bk-harness-ci') && !opts.force) {
    throw new Error(
      `bk-harness-ci already present in ${configPath}. Use --force to append again.`
    );
  }

  const block = generatePreCommitBlock();

  if (opts.dryRun) {
    process.stdout.write(`[dry-run] Would append to ${configPath}:\n${block}\n`);
    return { installed: true, path: configPath, framework: 'pre-commit', dryRun: true };
  }

  fs.appendFileSync(configPath, block, 'utf8');
  return { installed: true, path: configPath, framework: 'pre-commit' };
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  const opts = parseArgs(process.argv);
  const projectRoot = opts.projectRoot || process.env.BK_PROJECT_ROOT || process.cwd();

  // Auto-detect framework if not specified
  const framework = opts.framework || detectFramework(projectRoot);

  if (!['husky', 'pre-commit', 'native'].includes(framework)) {
    process.stderr.write(`[bk-precommit-install] Unknown framework: ${framework}\n`);
    process.exit(1);
  }

  process.stdout.write(`[bk-precommit-install] Installing pre-commit hook (framework: ${framework})...\n`);

  try {
    let result;
    if (framework === 'native') {
      result = installNative(projectRoot, opts);
    } else if (framework === 'husky') {
      result = installHusky(projectRoot, opts);
    } else if (framework === 'pre-commit') {
      result = installPreCommit(projectRoot, opts);
    }

    const prefix = result.dryRun ? '[dry-run] Would install' : 'Installed';
    process.stdout.write(`[bk-precommit-install] ${prefix} ${framework} hook at: ${result.path}\n`);
    process.exit(0);
  } catch (err) {
    process.stderr.write(`[bk-precommit-install] Error: ${err.message}\n`);
    process.exit(1);
  }
}

// Only run main() when executed directly (not when require()'d by tests)
if (require.main === module) {
  main();
}

module.exports = {
  detectFramework, generateNativeHook, generateHuskyHook,
  generatePreCommitBlock, installNative, installHusky, installPreCommit
};
